	// Phase 0: initialize tmp[i][j] to zero
	// ------------------------------------------------------------------
	traverser(tmp).for_each([&](auto state) {
		tmp[state] = (num_t)0;
	});

	// ------------------------------------------------------------------
	// Phase 1: tmp[i][j] += alpha * A[i][k] * B[k][j]
	//
	// Loop order: i -> k -> j
	//   * For fixed (i, k), A[i][k] is reused for all j.
	//   * j is innermost, matching the physical layout of both tmp and B,
	//     which improves spatial locality and enables vectorization.
	// ------------------------------------------------------------------
	traverser(tmp, A, B).template for_dims<'i'>([&](auto trav_i) {
		// i fixed here
		trav_i.template for_dims<'k'>([&](auto trav_ik) {
			// i and k fixed here

			const num_t a_ik = alpha * A[trav_ik];

			// walk j contiguously in both tmp and B
			trav_ik.template for_dims<'j'>([&](auto trav_ijk) {
				tmp[trav_ijk] += a_ik * B[trav_ijk];
			});
		});
	});

	// ------------------------------------------------------------------
	// Phase 2a: scale D by beta, D[i][l] *= beta
	// Separate pass keeps the update simple and friendly to vectorization.
	// ------------------------------------------------------------------
